SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='13fa94f9-8bab-5565-979f-c9d828edc4ae'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('71882480-8aa3-55a0-8f05-269dbad220ea','cfb827f0-36b4-5d16-8cbb-0640fa9d6e71')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='13fa94f9-8bab-5565-979f-c9d828edc4ae'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='13fa94f9-8bab-5565-979f-c9d828edc4ae'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('71882480-8aa3-55a0-8f05-269dbad220ea','cfb827f0-36b4-5d16-8cbb-0640fa9d6e71')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='13fa94f9-8bab-5565-979f-c9d828edc4ae'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='71882480-8aa3-55a0-8f05-269dbad220ea' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-customer-12-extra-free' AND q.fingerprint='e226c666ec30fae89c06345eef669303358963841198e150176127749c5ad7f1'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"customer-12-extra-free","status":"ok","value":{"customerProfileId":"13fa94f9-8bab-5565-979f-c9d828edc4ae","userId":"3a46f94f-b4f7-5a4f-97e2-bba29673a6d5","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"71882480-8aa3-55a0-8f05-269dbad220ea","semanticKey":"customer-controls-customer-12-extra-free","fingerprint":"e226c666ec30fae89c06345eef669303358963841198e150176127749c5ad7f1","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='e2bded57-4cd5-5046-9b72-9d69531d042d' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='cd432900-e3dc-53df-aa36-1e50dd787c4f' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"13fa94f9-8bab-5565-979f-c9d828edc4ae"},"prior":null,"committed":{"id":"13fa94f9-8bab-5565-979f-c9d828edc4ae","userId":"3a46f94f-b4f7-5a4f-97e2-bba29673a6d5","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='13fa94f9-8bab-5565-979f-c9d828edc4ae' AND c.user_id='3a46f94f-b4f7-5a4f-97e2-bba29673a6d5' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='customer-12-extra-free' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='a28cb3d5-ed90-59ba-840a-7686861d812d' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"13fa94f9-8bab-5565-979f-c9d828edc4ae","userId":"3a46f94f-b4f7-5a4f-97e2-bba29673a6d5","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='758952a9-6861-545a-8fd0-7ccc39658a09' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"3a46f94f-b4f7-5a4f-97e2-bba29673a6d5","track":"customer","customerProfileId":"13fa94f9-8bab-5565-979f-c9d828edc4ae","sourceCreationRevision":"0","sourceCreationReceipt":"71882480-8aa3-55a0-8f05-269dbad220ea","semanticKey":"customer_buyer_profile/13fa94f9-8bab-5565-979f-c9d828edc4ae/default-free-enrollment/v1"}'::jsonb)))=2));
